// 检查指定能效是否满足条件
bool check(vector<int>& ans, int mid , int days) {
    int res = 0;
    //计算每个果园所花费时间 累加
    for (int i = 0; i < ans.size(); i++) {
        int tmp = ans[i] / mid;
        if (ans[i] % mid) {
            tmp++;
        }
        res += tmp;
    }
    return res <= days;
}
​
