int main() {
    int m ,n;
    cin >> m >> n;
    vector<int> ans(m);
    // 天数小于无法果园数量无法完成
    if (n < m) {
        cout << -1;
        return 0;
    }
    int maxValue = 0;
    for (int i = 0; i < m; i++) {
        cin >> ans[i];
        maxValue = max(ans[i], maxValue);
    }

    int left = 1, right = maxValue;
    // 二分
    while (left <right) {
        int mid = (left + right) >> 1;
        if (check(ans, mid, n)) {
            right = mid;
        } else {
            left = mid +1;
        }
    }
​
    cout << left;
    return 0;

}

