package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
// 检查指定能效是否满足条件
func check(ans []int, mid int, days int) bool {
    res := 0
    // 计算每个果园所需时间并累加
    for _, v := range ans {
        tmp := v / mid
        if v%mid != 0 {
            tmp++
        }
        res += tmp
    }
    return res <= days
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
​
    // 读取第一行：m n
    line1, _ := reader.ReadString('\n')
    parts := strings.Fields(line1)
    m, _ := strconv.Atoi(parts[0])
    n, _ := strconv.Atoi(parts[1])
​
    // 特判：天数比果园少，不可能完成
    if n < m {
        fmt.Println(-1)
        return
    }
​
    // 读取第二行：m 个果园的工作量
    line2, _ := reader.ReadString('\n')
    strNums := strings.Fields(line2)
​
    ans := make([]int, m)
    maxValue := 0
    for i := 0; i < m; i++ {
        num, _ := strconv.Atoi(strNums[i])
        ans[i] = num
        if num > maxValue {
            maxValue = num
        }
    }
​
    // 二分查找最小可行能效
    left, right := 1, maxValue
    for left < right {
        mid := (left + right) / 2
        if check(ans, mid, n) {
            right = mid
        } else {
            left = mid + 1
        }
    }
​
    fmt.Println(left)
}
